/*
 * prog45_josephus –  Josephus survivor calculator
 *
 * The original binary implements a small state‑machine that:
 *
 *   1. Checks that exactly two numeric arguments are supplied.
 *   2. Prints "NO_INPUT"   when fewer than two arguments are given.
 *   3. Prints "BAD_INPUT"  when either argument cannot be parsed as a
 *      decimal integer.
 *   4. Prints "OUT_OF_RANGE" when the first argument (n) is larger than
 *      1 000 000 or the second argument (k) is larger than 1 000 000 000.
 *   5. Otherwise computes the Josephus survivor (1‑based) for the given
 *      n and k and prints it as a decimal number followed by a newline.
 *
 * The behaviour above reproduces the observable output of the original
 * obfuscated program for all possible inputs.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    /* 1. Argument count check */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* 2. Parse the first argument (n) */
    char *endptr;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1]) {          /* no digits were consumed */
        puts("BAD_INPUT");
        return 0;
    }

    /* 3. Parse the second argument (k) */
    long long k = strtoll(argv[2], &endptr, 10);
    if (endptr == argv[2]) {          /* no digits were consumed */
        puts("BAD_INPUT");
        return 0;
    }

    /* 4. Range checks (the original limits) */
    if (n > 1000000LL || k > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* 5. Josephus computation (1‑based result) */
    long long result = 0;                 /* survivor index for i = 1 */
    for (long long i = 2; i <= n; ++i) {
        result = (result + k) % i;
    }

    printf("%lld\n", result + 1);
    return 0;
}
